-- Live-update #9 (fix): spaceObject.Billboard.UpdateBillboardContents
--
-- BBMAP showed the billboard model's real texture order:
--   0 DiffuseMap -> Text   (TextureScaling U=0.2 window + TextScrollingCurve)
--   1 DiffuseMap -> Text2  (no scaling, Brightness driven by Text2FadeCurve)
--   2 FaceMap, 3 NoiseMap, 4 LineMap, 5 AdvertMap (Screen), 8 DiffuseMap (Base/hull)
--
-- The client put the news headline on index 1 (Text2 - faded, no window) and the
-- wanted caption on index 0 (Text - the scrolling window), so the marquee text
-- was never the headline. This swaps them: headlines -> Text (index 0),
-- bounty caption -> Text2, plus a TextureScaling 0.2 window on the VISIBLE panel.
INSERT INTO liveupdates
  (updateID, updateName, description, machoVersionMin, machoVersionMax,
   buildNumberMin, buildNumberMax, methodName, objectID, codeType, code)
VALUES
  (9, 'BillboardMapFix', 'billboard map fix',
   0, 999999, 1, 500000, 'UpdateBillboardContents', 'spaceObject.Billboard::Billboard', 'globalClassMethod',
   UNHEX(''))
ON DUPLICATE KEY UPDATE
  updateName=VALUES(updateName), description=VALUES(description),
  machoVersionMin=VALUES(machoVersionMin), machoVersionMax=VALUES(machoVersionMax),
  buildNumberMin=VALUES(buildNumberMin), buildNumberMax=VALUES(buildNumberMax),
  methodName=VALUES(methodName), objectID=VALUES(objectID),
  codeType=VALUES(codeType), code=VALUES(code);

-- +migrate Down
DELETE FROM liveupdates WHERE updateID=9;
